mapper.update:
UPDATE sys29_login_secure
   SET sys29_start_date = #{startDate},
       sys29_close_date = #{closeDate},
       sys29_public_ip  = #{publicIp},
       sys29_note       = #{note}
 WHERE sys29_login_secure_id = #{loginSecureId}
   AND sys29_company_id      = #{companyId}

